// Headline strip: Medicine stepped up, High-BP visits counted, Visits left out.
const root = rpt.mount('.rpt-tit-head');
if (!root) { return; }
const { esc, fmt, num, yes } = rpt;
const r = rpt.rows('A')[0];
const col = (big, color, label, line, title, few) => '<div' + (title ? ' title="' + esc(title) + '"' : '') + '>'
  + '<div class="rpt-big' + (few ? ' rpt-few' : '') + '"' + (color ? ' style="color:' + color + '"' : '') + '>' + esc(big) + '</div>'
  + '<div class="rpt-label">' + esc(label) + '</div><div class="rpt-line">' + esc(line) + '</div></div>';
if (!r) {
  root.innerHTML = '<div class="rpt-strip3">' + col('—', '', 'Medicine stepped up', rpt.NO_DATA) + col('—', '', 'High-BP visits counted', rpt.NO_DATA)
    + col('—', '', 'Visits left out', rpt.NO_DATA) + '</div>';
  return;
}
const N = num(r.uncontrolled_visits_n) || 0, n = num(r.stepped_up_n) || 0;
const a = num(r.excluded_too_recent_n) || 0, b = num(r.excluded_no_baseline_n) || 0;
const line = num(r.flag_below_pct);
const counts = fmt(n) + ' of ' + fmt(N) + ' high-BP visits stepped up';
let first;
if (yes(r.too_few)) {
  first = col('Too few visits', '', 'Medicine stepped up', rpt.needAtLeast(r.min_visits, N), counts, true);
} else if (num(r.titration_pct) === null) {
  first = col('—', '', 'Medicine stepped up', rpt.NO_DATA);
} else {
  const ok = line === null || num(r.titration_pct) >= line;
  first = col(rpt.pct(r.titration_pct), ok ? 'var(--controlled)' : 'var(--flag-bar)', 'Medicine stepped up',
    fmt(n) + ' of ' + fmt(N) + ' visits with BP 140/90 or above were followed by a stronger prescription', counts);
}
root.innerHTML = '<div class="rpt-strip3">' + first
  + col(fmt(N), 'var(--text-primary)', 'High-BP visits counted', 'BP 140/90 or above, last 90 days')
  + col(fmt(a + b), 'var(--text-muted)', 'Visits left out', fmt(a) + ' too recent to check, ' + fmt(b) + ' with no earlier prescription') + '</div>';

