// Bars by facility with a dashed flag line (PD-8: no month line chart).
const frame = (context.panel.data.series || []).find((s) => s.refId === 'A') || (context.panel.data.series || [])[0];
function col(n) { const f = frame && frame.fields.find((x) => x.name === n); if (!f) { return []; } return Array.from(f.values && f.values.buffer ? f.values.buffer : f.values); }
const C = chartColors;
const rv = context.grafana && context.grafana.replaceVariables;
const allowed = !rv || rv('${isAllowed}') === '1';
// Percent as DESIGN: whole, one decimal under 10%.
const pc = (v) => { const n = Math.round(10 * Number(v)) / 10; return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';
const ids = col('org_unit_id');
const name = col('org_unit_name'), lvl = col('level').map(Number), sel = col('is_selected');
const few = col('too_few'), flag = col('flag');
const N = col('uncontrolled_visits_n').map((v) => Number(v) || 0), n = col('stepped_up_n').map((v) => Number(v) || 0);
const p = col('titration_pct').map((v) => (v === null || v === undefined ? null : Number(v)));
const lineAt = Number(col('flag_below_pct')[0]);
// Facilities only: the bold "All places in view" row is the headline, not a bar.
let idx = ids.map((v, i) => i).filter((i) => !(yes(sel[i]) && lvl[i] < 3));
if (!idx.length) { idx = ids.map((v, i) => i); }
if (!idx.length) {
  return { graphic: allowed ? [{ type: 'text', left: 'center', top: 'middle', style: { text: 'No data for this place.', fontSize: 14, fill: C.muted } }] : [] };
}
// Same order as the table: flagged, too few, clean; then more high-BP visits first.
const rank = (i) => (yes(flag[i]) ? 0 : yes(few[i]) ? 1 : 2);
idx.sort((a, b) => rank(a) - rank(b) || N[b] - N[a] || String(name[a]).localeCompare(String(name[b])));
const colorOf = (i) => (yes(few[i]) || p[i] === null ? C.estimated : yes(flag[i]) ? C.noVisit : C.controlled);
const endLabel = (i) => (yes(few[i]) ? 'Too few visits · ' + fmt(N[i]) : p[i] === null ? 'No data' : pc(p[i]) + ' · ' + fmt(n[i]) + ' of ' + fmt(N[i]));
return {
  animation: false,
  grid: { left: 8, right: 24, top: 28, bottom: 8, containLabel: true },
  tooltip: tip((k) => {
    const i = idx[k];
    if (yes(few[i])) { return ['Too few visits', soft(fmt(N[i]) + ' high-BP visits; need at least 10')]; }
    if (p[i] === null) { return ['No data for this place.']; }
    return ['Stepped up: ' + pc(p[i]), soft(fmt(n[i]) + ' of ' + fmt(N[i]) + ' high-BP visits')];
  }, (k) => name[idx[k]], { axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(110,127,141,0.12)' } } }),
  xAxis: { type: 'value', min: 0, max: 100, interval: 25, axisLabel: { color: C.axis, fontSize: 11, formatter: (v) => v + '%' },
    splitLine: { lineStyle: { color: C.grid } } },
  yAxis: { type: 'category', inverse: true, data: idx.map((i) => name[i]), axisTick: { show: false },
    axisLabel: { color: C.text, fontSize: 12 }, axisLine: { lineStyle: { color: C.axisLine } } },
  series: [{
    type: 'bar', name: 'Stepped up', barMaxWidth: 26,
    data: idx.map((i) => ({ value: yes(few[i]) || p[i] === null ? 0 : p[i], itemStyle: { color: colorOf(i), borderRadius: [0, 2, 2, 0] } })),
    label: { show: true, position: 'right', color: C.text, fontSize: 12, backgroundColor: '#FFFFFF', padding: [1, 3], formatter: (q) => endLabel(idx[q.dataIndex]) },
    markLine: isNaN(lineAt) ? undefined : {
      silent: true, symbol: ['none', 'none'], animation: false,
      lineStyle: { type: 'dashed', color: C.text, width: 1.5 },
      label: { formatter: 'Flag line: ' + pc(lineAt), position: 'start', color: C.text, fontSize: 12 },
      data: [{ xAxis: lineAt }]
    }
  }]
};

